"""Line/regex parser for Lean 4 source files (no Lean toolchain required).

Recovers top-level declarations (theorem/lemma/def/abbrev/structure/class/
instance/inductive/opaque/axiom/alias), their fully-qualified names (tracking
`namespace`/`section`/`end`/`mutual`), signature text up to `:=` / `where` /
pattern-match bars, the attached `/-- ... -/` docstring, attributes (so that
`@[category ...]`, `formal_proof`, `deprecated` can be read), and line numbers.

Known limitations (measured in the report):
  * names generated by `@[to_additive]`, `@[simps]`, `deriving`, structure
    projections and auto-named anonymous instances are not real source text and
    are either skipped or approximated (anonymous instances get `inst<...>`);
  * declarations produced by macros/elaborators (e.g. `irreducible_def`,
    `notation`, `initialize_simps_projections`) are not recovered;
  * `variable` binders that are in scope are not added to the signature.
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field

KEYWORDS = (
    "theorem", "lemma", "def", "abbrev", "structure", "class", "instance",
    "inductive", "opaque", "axiom", "alias",
)
MODIFIERS = (
    "private", "protected", "noncomputable", "partial", "unsafe", "nonrec",
    "scoped", "local", "public", "meta",
)

# Lexical tokens that change comment/string state.  Order matters.
_LEX = re.compile(
    r'/--|/-!|/-|-/|--|"|(?<![\w\'.!?])\'(?:\\.|[^\\\'\n])\''
)


@dataclass
class Decl:
    kind: str
    name: str            # fully qualified (best effort)
    short: str           # name as written
    signature: str       # header text from keyword up to := / where / |
    doc: str             # attached /-- -/ docstring ('' if none)
    attrs: str           # raw attribute text, e.g. "@[simp, category research open]"
    line: int            # 1-based line of the keyword
    namespace: str
    modifiers: list = field(default_factory=list)
    anonymous: bool = False
    generated_from: str = ""   # set for names generated by @[to_additive explicitName]


def blank_comments(src: str):
    """Return (code, docs) where non-doc comments and doc comments are replaced
    by spaces (newlines kept) and `docs` is a list of (start, end, text) for
    `/-- -/` doc comments.  Module docs `/-! -/` are returned with kind 'mod'.
    Strings are kept verbatim in `code`."""
    out = []
    docs = []
    i = 0
    n = len(src)
    last = 0
    while True:
        m = _LEX.search(src, i)
        if not m:
            break
        tok = m.group(0)
        s = m.start()
        if tok == '"':
            # string literal: find closing quote, honouring escapes
            j = s + 1
            while j < n:
                c = src[j]
                if c == "\\":
                    j += 2
                    continue
                if c == '"':
                    break
                j += 1
            i = j + 1
            continue
        if tok.startswith("'"):
            i = m.end()
            continue
        if tok == "-/":
            # stray close (e.g. inside a string we failed to see); skip
            i = m.end()
            continue
        if tok == "--":
            j = src.find("\n", s)
            if j < 0:
                j = n
            out.append(src[last:s])
            out.append(" " * (j - s))
            last = j
            i = j
            continue
        # block comment (possibly doc / module doc), nested
        depth = 1
        j = m.end()
        while depth and j < n:
            a = src.find("/-", j)
            b = src.find("-/", j)
            if b < 0:
                j = n
                break
            if 0 <= a < b:
                depth += 1
                j = a + 2
            else:
                depth -= 1
                j = b + 2
        out.append(src[last:s])
        body = src[s:j]
        out.append(re.sub(r"[^\n]", " ", body))
        if tok == "/--":
            docs.append((s, j, body[3:-2].strip(), "doc"))
        elif tok == "/-!":
            docs.append((s, j, body[3:-2].strip(), "mod"))
        last = j
        i = j
    out.append(src[last:])
    return "".join(out), docs


_DECL_RE = re.compile(
    r"^(?P<lead>[ \t]*(?:@\[[^\n]*?\][ \t]*)?)"
    r"(?P<mods>(?:(?:" + "|".join(MODIFIERS) + r")[ \t]+)*)"
    r"(?P<kw>theorem|lemma|def|irreducible_def|abbrev|structure|class[ \t]+inductive|class|instance|inductive|opaque|axiom|alias)"
    r"(?=[ \t\n(])",
    re.M,
)
_NS_RE = re.compile(
    r"^[ \t]*(?:(?P<ns>namespace)[ \t]+(?P<nsname>[^\s]+)"
    r"|(?:@\[[^\]\n]*\][ \t]*)?(?:(?:noncomputable|public)[ \t]+)*(?P<sec>section)\b[ \t]*(?P<secname>[^\s]*)"
    r"|(?P<end>end)\b[ \t]*(?P<endname>[^\s]*)"
    r"|(?P<mutual>mutual)\b)",
    re.M,
)
_IDENT = r"(?:«[^»]+»|[^\s:(){}\[\]⦃⦄⟨⟩,]+)"
_OPEN = "([{⦃⟨"
_CLOSE = ")]}⦄⟩"


def _strip_attrs(gap: str):
    """If `gap` consists only of whitespace, attribute blocks `@[...]` and
    modifiers, return the concatenated attribute text; else None."""
    attrs = []
    i = 0
    n = len(gap)
    while i < n:
        c = gap[i]
        if c.isspace():
            i += 1
            continue
        if gap.startswith("@[", i):
            depth = 0
            j = i + 1
            in_str = False
            while j < n:
                ch = gap[j]
                if in_str:
                    if ch == "\\":
                        j += 2
                        continue
                    if ch == '"':
                        in_str = False
                elif ch == '"':
                    in_str = True
                elif ch == "[":
                    depth += 1
                elif ch == "]":
                    depth -= 1
                    if depth == 0:
                        break
                j += 1
            attrs.append(gap[i:j + 1])
            i = j + 1
            continue
        m = re.match(r"(?:" + "|".join(MODIFIERS) + r")\b", gap[i:])
        if m:
            i += m.end()
            continue
        return None
    return " ".join(attrs)


def _scan_signature(code: str, start: int, kw: str):
    """From `start` (just after the keyword) return (header_text, end_pos).
    Stops at `:=` / `where` / a line-leading `|` at bracket depth 0, or at the
    next command that starts in column 0."""
    depth = 0
    i = start
    n = len(code)
    in_str = False
    limit = min(n, start + 6000)
    while i < limit:
        c = code[i]
        if in_str:
            if c == "\\":
                i += 2
                continue
            if c == '"':
                in_str = False
            i += 1
            continue
        if c == '"':
            in_str = True
        elif c in _OPEN:
            depth += 1
        elif c in _CLOSE:
            depth = max(0, depth - 1)
        elif depth == 0:
            if c == ":" and code.startswith(":=", i):
                return code[start:i], i
            if c == "w" and code.startswith("where", i) and (i == 0 or not (code[i - 1].isalnum() or code[i - 1] in "_.'")) and (i + 5 >= n or not (code[i + 5].isalnum() or code[i + 5] in "_'")):
                return code[start:i], i
            if c == "\n":
                # look at next non-blank line
                j = i + 1
                while j < n and code[j] in " \t":
                    j += 1
                if j < n and code[j] == "|" and kw not in ("structure", "class"):
                    return code[start:i], i
                if j < n and j == i + 1 and code[j] not in "\n" and not code[j].isspace():
                    # something in column 0 => new command (unless it is a continuation token)
                    if not code.startswith(("|", ")", "]", "}", "⟩", ":", "→", "∀", "(", "{", "[", "⦃"), j):
                        return code[start:i], i
                if j < n and code.startswith("deriving", j):
                    return code[start:i], i
        i += 1
    return code[start:limit], limit


def parse_lean(src: str):
    """Parse a Lean 4 source string into a list of Decl."""
    code, docs = blank_comments(src)
    # line offsets
    line_starts = [0]
    for m in re.finditer("\n", code):
        line_starts.append(m.end())
    import bisect

    def line_of(pos):
        return bisect.bisect_right(line_starts, pos)

    # namespace events
    events = []
    for m in _NS_RE.finditer(code):
        events.append(m)
    ev_i = 0
    stack = []  # list of (kind, [parts])

    def cur_ns():
        parts = []
        for k, p in stack:
            if k == "ns":
                parts.extend(p)
        return ".".join(parts)

    doc_ends = {}
    for s, e, txt, kind in docs:
        if kind == "doc":
            doc_ends[e] = txt
    doc_end_list = sorted(doc_ends)

    out = []
    for m in _DECL_RE.finditer(code):
        pos = m.start()
        # apply namespace events before this declaration
        while ev_i < len(events) and events[ev_i].start() < pos:
            ev = events[ev_i]
            ev_i += 1
            if ev.group("ns"):
                stack.append(("ns", ev.group("nsname").split(".")))
            elif ev.group("sec") is not None and ev.group("sec"):
                stack.append(("sec", [ev.group("secname")]))
            elif ev.group("mutual"):
                stack.append(("mut", []))
            elif ev.group("end") is not None and ev.group("end"):
                name = ev.group("endname")
                if name and not re.match(r"^[\w.'«»]+$", name):
                    name = ""
                if stack:
                    if name:
                        # `end A.B` may close one `namespace A.B`, or `namespace A` + `namespace B`,
                        # or only the tail of `namespace X.A.B`.
                        parts = name.split(".")
                        while parts and stack:
                            k, p = stack[-1]
                            if k != "ns":
                                stack.pop()
                                break
                            if len(p) <= len(parts) and parts[-len(p):] == p:
                                parts = parts[: -len(p)]
                                stack.pop()
                            elif p[-len(parts):] == parts:
                                stack[-1] = (k, p[: -len(parts)])
                                parts = []
                            else:
                                stack.pop()
                                break
                    else:
                        stack.pop()
        kw = re.sub(r"\s+", " ", m.group("kw"))
        mods = m.group("mods").split()
        lead = m.group("lead")
        # skip things that are indented inside a structure/where block (fields are not decls)
        # but keep indented decls (Mathlib sometimes indents inside sections)
        kw_end = m.end()
        rest = code[kw_end:kw_end + 400]
        anonymous = False
        name = ""
        if kw == "instance":
            mm = re.match(r"\s*(?:\(\s*priority\s*:=\s*[^)]*\)\s*)?", rest)
            r2 = rest[mm.end():]
            nm = re.match(_IDENT, r2)
            if nm and not r2.startswith(("[", "{", "(", ":", "⦃")) and nm.group(0) not in ("where",):
                name = nm.group(0)
                sig_start = kw_end + mm.end() + nm.end()
            else:
                anonymous = True
                sig_start = kw_end + mm.end()
        elif kw == "alias" and rest.lstrip().startswith("⟨"):
            # alias ⟨mp_name, mpr_name⟩ := foo_iff  -> one Decl per named direction
            tup = re.match(r"\s*⟨([^⟩]*)⟩\s*:=\s*([^\s]+)?", rest)
            if not tup:
                continue
            target = tup.group(2) or ""
            ns = cur_ns()
            for idx, part in enumerate(tup.group(1).split(",")):
                part = part.strip()
                if not part or part == "_":
                    continue
                full = part[len("_root_."):] if part.startswith("_root_.") else (ns + "." + part if ns else part)
                direction = "mp (forward)" if idx == 0 else "mpr (backward)"
                k = bisect.bisect_right(doc_end_list, pos) - 1
                doc = ""
                if k >= 0 and _strip_attrs(code[doc_end_list[k]:pos]) is not None:
                    doc = doc_ends[doc_end_list[k]]
                out.append(Decl(kind="alias", name=full, short=part,
                                signature=f":= {target}  -- {direction} direction of `{target}`",
                                doc=doc, attrs=lead.strip(), line=line_of(pos), namespace=ns,
                                modifiers=mods))
            continue
        else:
            nm = re.match(r"\s*(" + _IDENT + ")", rest)
            if not nm:
                continue
            name = nm.group(1)
            sig_start = kw_end + nm.end()
            if name in ("where", ":=", "|"):
                continue
        sig, sig_end = _scan_signature(code, sig_start, kw)
        if kw == "alias":
            # alias foo := bar   /  alias ⟨a, b⟩ := iff
            sig = code[sig_start:sig_end + 2 + 200].split("\n")[0]
        sig = re.sub(r"[ \t]*\n[ \t]*", "\n", sig).strip()
        sig = re.sub(r"[ \t]+", " ", sig)
        name = re.sub(r"\.\{[^}]*\}", "", name).rstrip(".")  # universe params: `PMF.{u}` -> `PMF`
        if anonymous:
            name = anon_instance_name(sig, cur_ns())
        # docstring + attribute association
        lead_attrs = lead.strip()
        doc = ""
        attrs = lead_attrs
        k = bisect.bisect_right(doc_end_list, pos) - 1
        # gap between preceding doc end and decl must be only attributes/modifiers.
        # The nearest doc may sit *inside* an attribute (e.g. `@[to_additive "/-- add doc -/"]`),
        # in which case the declaration's own docstring is the one before it.
        for kk in range(k, max(-1, k - 3), -1):
            de = doc_end_list[kk]
            a = _strip_attrs(code[de:pos])
            if a is not None:
                doc = doc_ends[de]
                attrs = (a + " " + lead_attrs).strip()
                break
        if not doc:
            # attributes on preceding lines without a docstring
            ls = line_starts[line_of(pos) - 1]
            back = code[max(0, ls - 800):ls]
            mm = re.search(r"((?:@\[(?:[^\[\]]|\[[^\[\]]*\])*\]\s*)+)$", back)
            if mm:
                attrs = (mm.group(1).strip() + " " + lead_attrs).strip()
        ns = cur_ns()
        short = name
        if name.startswith("_root_."):
            full = name[len("_root_."):]
        elif ns and kw != "alias":
            full = ns + "." + name
        elif ns:
            full = ns + "." + name if not name.startswith("⟨") else name
        else:
            full = name
        if "private" in mods:
            pass
        kw = "def" if kw == "irreducible_def" else kw
        out.append(Decl(kind=kw.replace("class inductive", "class"), name=full, short=short,
                        signature=sig[:3000], doc=doc, attrs=attrs, line=line_of(pos),
                        namespace=ns, modifiers=mods, anonymous=anonymous))
        # @[to_additive explicitName] generates a second declaration with that name.
        ta = _TO_ADD.search(attrs)
        if ta and not ta.group("existing"):
            add = ta.group("name")
            inner = [doc_ends[e] for e in doc_end_list if (pos - 1200 < e < pos and doc_ends[e] != doc
                                                           and re.match(r"\s*\]", code[e:pos])
                                                           and ":=" not in code[e:pos])]
            add_full = add[len("_root_."):] if add.startswith("_root_.") else (ns + "." + add if ns else add)
            if add_full != full:
                out.append(Decl(kind=kw.replace("class inductive", "class"), name=add_full, short=add,
                                signature=sig[:3000], doc=(inner[-1] if inner else doc),
                                attrs=attrs, line=line_of(pos), namespace=ns, modifiers=mods,
                                generated_from=full))
    return out


_TO_ADD = re.compile(r"to_additive(?:\s+\(attr\s*:=[^)]*\))?(?:\s+\(reorder\s*:=[^)]*\))?\s+(?P<existing>existing\s+)?"
                     r"(?P<name>(?!existing\b)[A-Za-z_][\w.']*)")


def module_docs(src: str):
    """Return the list of `/-! ... -/` module doc texts."""
    _, docs = blank_comments(src)
    return [t for s, e, t, k in docs if k == "mod"]


_BINDER = re.compile(r"[\(\{\[⦃]([^()\[\]{}⦃⦄]*)[\)\}\]⦄]")
_CONST = re.compile(r"(?<![\w.'])([A-Za-z_][\w']*(?:\.[A-Za-z_][\w']*)*)")


def anon_instance_name(sig: str, ns: str) -> str:
    """Approximate Lean 4's auto-generated name for an anonymous `instance`.

    Lean builds `inst` + the head constants of the instance type (omitting
    components already in the current namespace), plus `Of` + the classes of
    instance-implicit hypotheses.  This heuristic reproduces the common cases
    (e.g. `instance [DecidableEq V] : Fintype (SimpleGraph V)` ->
    `instFintypeSimpleGraphOfDecidableEq`, `namespace Hamming ... instance :
    PseudoMetricSpace (Hamming β)` -> `Hamming.instPseudoMetricSpace`) but is not exact.
    """
    flat = " ".join(sig.split())
    # split binders from the conclusion at the last top-level ':'
    depth = 0
    cut = -1
    for i, c in enumerate(flat):
        if c in "([{⦃⟨":
            depth += 1
        elif c in ")]}⦄⟩":
            depth -= 1
        elif c == ":" and depth == 0 and not flat.startswith(":=", i):
            cut = i
    binders, concl = (flat[:cut], flat[cut + 1:]) if cut >= 0 else ("", flat)
    bound = set()
    for b in _BINDER.findall(binders):
        if ":" in b:
            bound.update(b.split(":")[0].split())
    nsparts = set(ns.split(".")) if ns else set()

    def heads(text):
        out = []
        for m in _CONST.finditer(text):
            tok = m.group(1)
            last = tok.split(".")[-1]
            if tok in bound or len(last) <= 1 or not last[0].isupper() or last in nsparts:
                continue
            if last not in out:
                out.append(last)
        return out

    concl = re.sub(r"^∀\s*[^,]*,", "", concl.strip())
    name = "inst" + "".join(heads(concl))
    hyps = [h for b in re.findall(r"\[([^\[\]]*)\]", binders) for h in heads(b.split(":")[-1])[:1]]
    if hyps:
        name += "Of" + "".join(hyps)
    return name
